import zipfile
import json
import re
import os
import shutil

# Prefer lxml when available; fall back to stdlib ElementTree otherwise.
try:
    from lxml import etree  # type: ignore
    USING_LXML = True
except Exception:
    import xml.etree.ElementTree as etree  # type: ignore
    USING_LXML = False

# Paths
TEMPLATE = 'event_announcement_template.hwpx'
DATA_FILE = 'event_data.json'
OUTPUT = '/root/event_announcement_ready.hwpx'
TEMP_DIR = '/tmp/hwpx_work'


def _localname(tag: str) -> str:
    if not isinstance(tag, str):
        return ''
    if tag.startswith('{') and '}' in tag:
        return tag.rsplit('}', 1)[1]
    return tag


def _guess_hp_namespace(root) -> str | None:
    # lxml: root.nsmap exists, ElementTree: no nsmap attribute
    nsmap = getattr(root, 'nsmap', None)
    if isinstance(nsmap, dict):
        for prefix, uri in nsmap.items():
            if prefix == 'hp':
                return uri
        for prefix, uri in nsmap.items():
            if not uri:
                continue
            low = uri.lower()
            if 'hwpml' in low or 'hancom' in low:
                return uri

    # Fallback: infer from tags
    for elem in root.iter():
        tag = getattr(elem, 'tag', '')
        if isinstance(tag, str) and tag.startswith('{') and '}' in tag:
            uri = tag[1:].split('}', 1)[0]
            local = tag.rsplit('}', 1)[1]
            if local in ('p', 't', 'section'):
                return uri
    return None


def _parse_xml(raw: bytes):
    if USING_LXML:
        # lxml handles xml declaration/encoding well
        return etree.fromstring(raw)

    # ElementTree: best effort decode/parse
    # HWPX XML is typically UTF-8; if not, fall back to bytes parse.
    try:
        return etree.fromstring(raw)
    except Exception:
        text = raw.decode('utf-8', errors='replace')
        return etree.fromstring(text.encode('utf-8'))


def _serialize_xml(root) -> bytes:
    if USING_LXML:
        # Use a stable, explicit declaration; standalone is optional but harmless.
        return etree.tostring(
            root,
            xml_declaration=True,
            encoding='UTF-8',
            standalone=True,
        )

    # ElementTree
    xml_bytes = etree.tostring(root, encoding='utf-8', xml_declaration=True)
    return xml_bytes


# Load JSON data
with open(DATA_FILE, 'r', encoding='utf-8') as f:
    data = json.load(f)

# Extract HWPX
if os.path.exists(TEMP_DIR):
    shutil.rmtree(TEMP_DIR)
os.makedirs(TEMP_DIR)

with zipfile.ZipFile(TEMPLATE, 'r') as zin:
    entry_list = zin.namelist()
    zin.extractall(TEMP_DIR)

# Process each XML file
for entry in entry_list:
    filepath = os.path.join(TEMP_DIR, entry)
    if not os.path.isfile(filepath):
        continue
    if not (entry.endswith('.xml') or entry.endswith('.hpf')):
        continue

    with open(filepath, 'rb') as f:
        raw = f.read()

    # Skip files without any placeholder fragments
    if b'{{' not in raw and b'}}' not in raw:
        continue

    # Try XML-aware paragraph-level replacement
    try:
        root = _parse_xml(raw)
    except Exception:
        root = None

    if root is None:
        # String-level fallback
        text = raw.decode('utf-8', errors='replace')
        for key, value in data.items():
            text = text.replace('{{' + key + '}}', str(value))
        if '{{' in text:
            print(f'WARNING: Remaining placeholders in {entry}')
        with open(filepath, 'w', encoding='utf-8') as f:
            f.write(text)
        continue

    hp_ns = _guess_hp_namespace(root)
    if not hp_ns:
        # String-level fallback
        text = raw.decode('utf-8', errors='replace')
        for key, value in data.items():
            text = text.replace('{{' + key + '}}', str(value))
        if '{{' in text:
            print(f'WARNING: Remaining placeholders in {entry}')
        with open(filepath, 'w', encoding='utf-8') as f:
            f.write(text)
        continue

    p_tag = f'{{{hp_ns}}}p'
    t_tag = f'{{{hp_ns}}}t'

    modified_paras = []

    for p_elem in root.iter(p_tag):
        t_elements = list(p_elem.iter(t_tag))
        if not t_elements:
            continue

        full_text = ''.join((t.text or '') for t in t_elements)
        if '{{' not in full_text:
            continue

        replaced_text = full_text
        for key, value in data.items():
            replaced_text = replaced_text.replace('{{' + key + '}}', str(value))

        if replaced_text == full_text:
            continue

        # Redistribute: put all text in first <hp:t>, clear the rest
        t_elements[0].text = replaced_text
        for t in t_elements[1:]:
            t.text = ''

        modified_paras.append(p_elem)

    # Remove layout cache elements (lineSegArray / linesegarray / etc.) from modified paragraphs
    for p_elem in modified_paras:
        for child in list(p_elem):
            local = _localname(getattr(child, 'tag', '')).lower()
            if 'lineseg' in local:
                p_elem.remove(child)

    out_bytes = _serialize_xml(root)
    with open(filepath, 'wb') as f:
        f.write(out_bytes)

# Rebuild ZIP with mimetype first and stored (if present)
with zipfile.ZipFile(OUTPUT, 'w') as zout:
    if 'mimetype' in entry_list:
        mime_path = os.path.join(TEMP_DIR, 'mimetype')
        zout.write(mime_path, 'mimetype', compress_type=zipfile.ZIP_STORED)

    for entry in entry_list:
        if entry == 'mimetype':
            continue
        filepath = os.path.join(TEMP_DIR, entry)
        if os.path.isfile(filepath):
            zout.write(filepath, entry, compress_type=zipfile.ZIP_DEFLATED)
        elif os.path.isdir(filepath):
            # Preserve directory entries if they exist in the original package
            zout.writestr(entry, '')

print('Output written to', OUTPUT)

# Validation: check no placeholders remain
with zipfile.ZipFile(OUTPUT, 'r') as z:
    for name in z.namelist():
        content = z.read(name)
        try:
            text = content.decode('utf-8')
        except Exception:
            continue
        matches = re.findall(r'\{\{.*?\}\}', text)
        if matches:
            print(f'ERROR: Remaining placeholders in {name}: {matches}')

print('Validation complete.')

